def cobs_encode(data):
    out = bytearray()
    block_start = 0
    out.append(0)
    count = 0
    for byte in data:
        if byte == 0:
            out[block_start] = count + 1
            block_start = len(out)
            out.append(0)
            count = 0
        else:
            out.append(byte)
            count += 1
            if count == 254:
                out[block_start] = 255
                block_start = len(out)
                out.append(0)
                count = 0
    out[block_start] = count + 1
    return bytes(out)


def cobs_decode(data):
    out = bytearray()
    n = len(data)
    i = 0
    while i < n:
        code = data[i]
        if code == 0:
            raise ValueError("zero byte in COBS-encoded data")
        end = i + code
        if end > n:
            raise ValueError("truncated COBS group")
        block = data[i + 1:end]
        if 0 in block:
            raise ValueError("zero byte in COBS-encoded data")
        out += block
        i = end
        if code < 255:
            if i < n:
                out.append(0)
        else:
            if i >= n:
                raise ValueError("trailing code byte 255 with no following group")
    return bytes(out)
